with cte0 (mq_customerId,mq_spent,mq_payments) as (select sp1_0.customer_id,sum(sp1_0.amount),count(*) from sp_payment sp1_0 group by 1),cte1 (mq_customerId,mq_spent,mq_payments) as (select sp2_0.customer_id,sum(sp2_0.amount),count(*) from sp_payment sp2_0 group by 1) select so1_0.id,c1_0.id,c1_0.name,c1_0.region_id,sr1_0.name,cte01_0.mq_spent,r1_0.id,r1_0.name,r1_0.region_id,sr2_0.name,cte11_0.mq_spent from sp_order so1_0 left join sp_customer c1_0 on c1_0.id=so1_0.customer_id left join cte0 cte01_0 on cte01_0.mq_customerId=so1_0.customer_id left join sp_customer r1_0 on r1_0.id=so1_0.referrer_id left join cte1 cte11_0 on cte11_0.mq_customerId=so1_0.referrer_id left join sp_region sr1_0 on sr1_0.id=c1_0.region_id left join sp_region sr2_0 on sr2_0.id=r1_0.region_id order by 1;
